# Unit test of the Hindsight API docs page without third-party origins: /agent/home-render.sh's own location for the
# docs page (= /memory-api/docs under the /memory-api route: the CDN rewrites and the Content-Security-Policy) and the
# pinned swagger-ui copy /setup/install-swagger-ui.sh puts
# in the image. Fully OFFLINE: nginx with the rendered config on test-local ports, a stub hindsight-api answering
# FastAPI's REAL Swagger UI page (generated by the image's own fastapi, the one hindsight-api runs) and a minimal
# openapi.json, test-local state under /tmp/docs-assets-smoke.
#
# Properties proven (each check FAILS if the property is removed):
#   1. this test and home-render.sh parse (bash -n)
#   2. the pinned copy: /opt/swagger-ui-dist holds the bundle, the stylesheet, the icon, the LICENSE, the NOTICE and
#      package.json at the installer's pinned version, and the files match the SHA256SUMS written at install
#   3. through nginx, in both hindsight-api modes (rewrite: the proxy rewrites the openapi.json reference; native:
#      the API's own --root-path): the docs page names no third-party origin - no cdn.jsdelivr.net,
#      fastapi.tiangolo.com or fonts.googleapis.com, no absolute http(s) asset URL at all - and loads its bundle,
#      stylesheet and icon from /memory-api/__swagger/, which answers the image's files byte for byte; the page and
#      the assets carry the 'self'-only Content-Security-Policy; the assets refuse POST (403); the page still points
#      swagger at /memory-api/openapi.json and carries the badge exactly once
#   4. PLANTED CONTROL: a home-render.sh copy without the CDN rewrite serves a page that loads swagger-ui from
#      cdn.jsdelivr.net, and check 3's scan fails it, naming that origin

D=/tmp/docs-assets-smoke
rm -rf "${D:?}"
mkdir -p "${D}"

BASE_DIR="$(cd "$(dirname "$0")" && pwd)"
AGENT_DIR="${BASE_DIR%/}/agent"
SWAGGER_UI_DIR=${SWAGGER_UI_DIR:-/opt/swagger-ui-dist}
INSTALLER="${BASE_DIR%/}/setup/install-swagger-ui.sh"
# the python hindsight-api runs on (its fastapi renders the real page); /setup/install-hindsight.sh's uv tool
HS_PY=${HS_PY:-$(ls /home/hindsight/.local/share/uv/tools/hindsight-api/bin/python 2>/dev/null)}
PORT_HOME=18511
PORT_API=18512
PIDS=()

cleanup()
{
	for P in "${PIDS[@]}"; do kill "${P}" 2>/dev/null; done
}
trap cleanup EXIT

fail()
{
	echo "Test-docs-assets FAILED: $1"
	exit 1
}

# --- 1. syntax ---
bash -n "${AGENT_DIR}/home-render.sh" || fail "bash -n home-render.sh"
bash -n "${INSTALLER}" || fail "bash -n install-swagger-ui.sh"
bash -n "$0" || fail "bash -n $0"
echo "ok 1 - syntax"

# --- 2. the pinned copy ---
PIN=$(sed -n 's/^export SWAGGER_UI_VERSION=//p' "${INSTALLER}")
[ -n "${PIN}" ] || fail "install-swagger-ui.sh pins no SWAGGER_UI_VERSION"
for F in swagger-ui-bundle.js swagger-ui-bundle.js.LICENSE.txt swagger-ui.css favicon-32x32.png LICENSE NOTICE package.json SHA256SUMS; do
	[ -s "${SWAGGER_UI_DIR}/${F}" ] || fail "${SWAGGER_UI_DIR}/${F} is missing"
done
VER=$(python3 -c 'import json, sys; d = json.load(open(sys.argv[1])); print(d["name"] + "@" + d["version"])' "${SWAGGER_UI_DIR}/package.json")
[ "${VER}" == "swagger-ui-dist@${PIN}" ] || fail "the copy is ${VER}, the installer pins swagger-ui-dist@${PIN}"
grep -q "Apache License" "${SWAGGER_UI_DIR}/LICENSE" || fail "the copy's LICENSE is not swagger-ui's Apache-2.0 text"
( cd "${SWAGGER_UI_DIR}" && sha256sum -c --quiet SHA256SUMS ) || fail "the copy does not match its SHA256SUMS"
echo "ok 2 - ${VER} in ${SWAGGER_UI_DIR} (bundle, stylesheet, icon, LICENSE, NOTICE), matching its SHA256SUMS"

if [ -z "${HS_PY}" ] || ! command -v nginx > /dev/null; then
	echo "ok 3 - (skipped: no hindsight-api python or no nginx in this context)"
	echo "Test-docs-assets succeeded"
	exit 0
fi

# the real pages: FastAPI's own Swagger UI html, as hindsight-api serves it in each mode
for M in rewrite native; do
	OPENAPI=/openapi.json
	[ "${M}" == "native" ] && OPENAPI=/memory-api/openapi.json
	"${HS_PY}" -c 'import sys
from fastapi.openapi.docs import get_swagger_ui_html
sys.stdout.write(get_swagger_ui_html(openapi_url=sys.argv[1], title="Hindsight API - Swagger UI").body.decode())' "${OPENAPI}" > "${D}/docs-${M}.html" \
		|| fail "the image's fastapi did not render its Swagger UI page"
done
grep -q 'cdn.jsdelivr.net' "${D}/docs-rewrite.html" || fail "the real page no longer loads swagger-ui from cdn.jsdelivr.net - re-check the rewrite against it"
cat > "${D}/stub.py" << 'PYEOF'
import sys
from http.server import BaseHTTPRequestHandler, HTTPServer
D = sys.argv[2]
class H(BaseHTTPRequestHandler):
    def log_message(self, *a):
        pass
    def do_GET(self):
        if self.path == "/docs":
            b, t = open(D + "/docs-" + open(D + "/mode").read().strip() + ".html", "rb").read(), "text/html; charset=utf-8"
        elif self.path == "/openapi.json":
            b, t = b'{"openapi": "3.1.0", "info": {"title": "stub", "version": "0"}, "paths": {}}', "application/json"
        else:
            self.send_response(404); self.end_headers(); return
        self.send_response(200)
        self.send_header("Content-Type", t)
        self.send_header("Content-Length", str(len(b)))
        self.end_headers()
        self.wfile.write(b)
HTTPServer(("127.0.0.1", int(sys.argv[1])), H).serve_forever()
PYEOF
echo rewrite > "${D}/mode"
python3 "${D}/stub.py" "${PORT_API}" "${D}" > "${D}/stub.log" 2>&1 &
PIDS+=($!)

render()
{
	# render <home-render.sh> <ui dir> <mode> - the config with hindsight alone, on the test ports
	UI_DIR=$2 HINDSIGHT_API_ROOT_PATH=$3 UI_HINDSIGHT=true UI_HEADLAMP=false UI_VIBE_KANBAN=false UI_TMUX=false \
		UI_TMUX_AGENT=false UI_CLAUDE_MEM=false UI_LOGLEARNER=false COMMS_UI_ENABLED=false UI_LISTEN_HOST=127.0.0.1 \
		UI_PORT_HOME=${PORT_HOME} UI_PORT_HINDSIGHT_API=${PORT_API} UI_PORT_HINDSIGHT_UI=18513 SWAGGER_UI_DIR=${SWAGGER_UI_DIR} \
		bash "$1" > /dev/null || fail "home-render.sh ($3)"
}
NGINX_PID=""
serve()
{
	# serve <ui dir> - (re)start nginx on the rendered config and wait for the docs page
	[ -n "${NGINX_PID}" ] && kill "${NGINX_PID}" 2>/dev/null && wait "${NGINX_PID}" 2>/dev/null
	nginx -c "$1/home/nginx.conf" -g "daemon off;" > "${D}/nginx.log" 2>&1 &
	NGINX_PID=$!
	PIDS+=("${NGINX_PID}")
	for _ in $(seq 1 50); do curl -s -o /dev/null --max-time 1 "http://127.0.0.1:${PORT_HOME}/memory-api/docs" && return 0; sleep 0.2; done
	fail "nginx did not answer on the rendered config: $(tail -3 "${D}/nginx.log")"
}
# scan <page file> - prints each third-party origin or absolute asset URL the page names; exit 1 when any
scan()
{
	{ grep -oE 'cdn\.jsdelivr\.net|fastapi\.tiangolo\.com|fonts\.googleapis\.com|fonts\.gstatic\.com|unpkg\.com' "$1"
	  grep -oE '(src|href)="https?://[^"]+"' "$1"; } | sort -u | grep . && return 1
	return 0
}

# --- 3. both modes through nginx ---
H=http://127.0.0.1:${PORT_HOME}
for M in rewrite native; do
	echo "${M}" > "${D}/mode"
	render "${AGENT_DIR}/home-render.sh" "${D}/ui-${M}" "${M}"
	serve "${D}/ui-${M}"
	curl -s -D "${D}/page-${M}.hdr" -o "${D}/page-${M}.html" --max-time 5 "${H}/memory-api/docs"
	OFF=$(scan "${D}/page-${M}.html") || fail "${M}: the docs page still names a third-party origin: $(echo "${OFF}" | tr '\n' ' ')"
	for P in 'src="/memory-api/__swagger/swagger-ui-bundle.js"' 'href="/memory-api/__swagger/swagger-ui.css"' 'href="/memory-api/__swagger/favicon-32x32.png"' \
	         "'/memory-api/openapi.json'"; do
		grep -qF "${P}" "${D}/page-${M}.html" || fail "${M}: the docs page lacks ${P}"
	done
	[ "$(grep -o 'id="do-agent-aws-home"' "${D}/page-${M}.html" | wc -l)" == "1" ] || fail "${M}: the docs page does not carry the badge exactly once"
	grep -qi "^content-security-policy: default-src 'self'; script-src 'self' 'unsafe-inline';" "${D}/page-${M}.hdr" \
		|| fail "${M}: the docs page carries no 'self'-only Content-Security-Policy: $(grep -i '^content-security' "${D}/page-${M}.hdr")"
	for F in swagger-ui-bundle.js swagger-ui.css favicon-32x32.png; do
		curl -s -D "${D}/asset.hdr" -o "${D}/asset.out" --max-time 5 "${H}/memory-api/__swagger/${F}"
		cmp -s "${D}/asset.out" "${SWAGGER_UI_DIR}/${F}" || fail "${M}: /memory-api/__swagger/${F} is not the image's file ($(head -1 "${D}/asset.hdr"))"
		grep -qi "^content-security-policy: default-src 'self'" "${D}/asset.hdr" || fail "${M}: /memory-api/__swagger/${F} carries no Content-Security-Policy"
	done
	HTTP=$(curl -s -o /dev/null -w '%{http_code}' --max-time 5 -X POST "${H}/memory-api/__swagger/swagger-ui.css")
	[ "${HTTP}" == "403" ] || fail "${M}: a POST to the swagger-ui copy was not refused (expected 403, got ${HTTP})"
done
echo "ok 3 - both modes: the docs page names no third-party origin, loads swagger-ui from /memory-api/__swagger/ (the image's bytes), 'self'-only CSP on page and assets, POST 403, openapi.json and the badge through the proxy"

# --- 4. planted control: no CDN rewrite ---
sed "/sub_filter 'https:\/\/cdn.jsdelivr.net\/npm\/swagger-ui-dist@5\/'/d" "${AGENT_DIR}/home-render.sh" > "${D}/mutant-home-render.sh"
grep -q 'cdn.jsdelivr.net/npm/swagger-ui-dist@5/' "${D}/mutant-home-render.sh" && fail "could not plant the control"
echo rewrite > "${D}/mode"
render "${D}/mutant-home-render.sh" "${D}/ui-mutant" rewrite
serve "${D}/ui-mutant"
curl -s -o "${D}/page-mutant.html" --max-time 5 "${H}/memory-api/docs"
OFF=$(scan "${D}/page-mutant.html") && fail "PLANTED CONTROL: without the rewrite the docs page passed the scan"
echo "${OFF}" | grep -qx 'cdn.jsdelivr.net' || fail "the control failed for the wrong reason: ${OFF}"
echo "ok 4 - planted control: without the CDN rewrite the page names $(echo "${OFF}" | head -1 | tr -d '\n') and the scan fails it"

rm -rf "${D:?}"
echo "Test-docs-assets succeeded"
